/** The cut for a capital height of `capPx` CSS px, and whether to draw its engraving. */
export function wordmarkFor(capPx: number): { cut: WordmarkCut; engraved: boolean } {
  if (capPx >= WORDMARK_FLOORS.engraved) return { cut: WORDMARK_DISPLAY, engraved: true }
  if (capPx >= WORDMARK_FLOORS.display) return { cut: WORDMARK_DISPLAY, engraved: false }
  return { cut: WORDMARK_TEXT, engraved: false }
}
